import csv
import io
import json

FIELDS = ("id", "name")


def _normalize(row):
    """Return a new dict with only the export fields, stringified; '' for missing/None."""
    clean = {}
    for key in FIELDS:
        value = row.get(key)
        clean[key] = "" if value is None else str(value)
    return clean


def _to_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(FIELDS)
    for row in rows:
        writer.writerow([row[key] for key in FIELDS])
    return buffer.getvalue()


def _to_json(rows):
    return json.dumps(list(rows), ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {"csv": _to_csv, "json": _to_json}


def export_rows(rows, format):
    serializer = _SERIALIZERS.get(format) if isinstance(format, str) else None
    if serializer is None:
        raise ValueError("unsupported format")
    return serializer(_normalize(row) for row in rows)
